import { Component } from 'react'
import { Container, CustomText } from '../../../../../components'
import { LANG_STRINGS } from '../../../../../lang'
import { ContactStyle } from './index.style'
import { DisplayFlexCCC, Row } from '../../../../../commonStyle/index.style'
import { AgentColorPallette } from '../../../../../configs/colorPallete'
import { CONSULTANT } from '../../../../../images'
import { WHATS_APP_URL } from '../../../../../constants/appUrls'
import { WHATS_APP_NUMBER } from '../../constants'
import searchBuilder from '../../../../../helpers/queryBuilder'
import { isWebView } from '../../../../../helpers/utility'

class Contact extends Component {
  handleClick = (type) => {
    // this is not working in web view
    if (isWebView()) return false

    switch (type) {
      case 'WHATSAPP': {
        const queryString = searchBuilder({
          phone: WHATS_APP_NUMBER
        })
        const url = encodeURI(`${WHATS_APP_URL}${queryString}`)
        // this to start timer for whatsAppBtn and disable the btn for 60 sec.
        window.open(url, '_blank')
        return true
      }
      case 'TELEPON': {
        window.open('tel:+628789008080')
        return true
      }
      default:
        break
    }
  }

  getTitleImgContainer = (title, icon, className, isIcon) => {
    return (
      <DisplayFlexCCC className={className} onClick={() => this.handleClick(title)}>
        <div>
          {
            isIcon ? <i className={icon} />
              : (<img className='img' src={icon} alt='consultant' />)
          }
        </div>
        <CustomText
          size='14px'
          top='6px'
          weight={800}
          color={AgentColorPallette.black}
        >
          {title}
        </CustomText>
      </DisplayFlexCCC>
    )
  }

  render () {
    return (
      <Container
        title={LANG_STRINGS.contactAConsultant}
        displayBackButton
        hideBottomTabs
      >
        <ContactStyle>
          <DisplayFlexCCC>
            <CustomText
              size='14px'
              bottom='30px'
              color={AgentColorPallette.black}
            >
              {LANG_STRINGS.yourCurrentConsultant}
            </CustomText>
            {this.getTitleImgContainer('Andrew', CONSULTANT, 'contact-icon-box')}
          </DisplayFlexCCC>
          <CustomText
            size='14px'
            top='30px'
            bottom='30px'
            color={AgentColorPallette.black}
            textAlign='center'
          >
            {LANG_STRINGS.contactVia}
          </CustomText>
          <Row justify='space-evenly'>
            {this.getTitleImgContainer('WHATSAPP', 'fab fa-whatsapp', 'contact-via', true)}
            {this.getTitleImgContainer('TELEPON', 'fas fa-phone phone-rotate', 'contact-via', true)}
          </Row>
        </ContactStyle>
      </Container>
    )
  }
}

export default Contact
